import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("info");

  // Démarrer la caméra
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } })
      .then(s => {
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      })
      .catch(err => {
        setMessage("❌ Impossible d'accéder à la caméra : " + err.message);
        setMessageType("error");
      });

    return () => {
      if (stream) stream.getTracks().forEach(track => track.stop());
    };
  }, []);

  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    setMessage("⏳ Capture et analyse...");

    try {
      // Capture l'image depuis la vidéo
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL('image/jpeg');

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("🔍 RAW RESPONSE:", response);
      console.log("📊 DATA:", data);

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setMessage(`✅ ${name} - Confiance: ${confidence}%`);
        setMessageType("success");
      } else {
        setMessage(String(data.message || data.error || "Visage non reconnu"));
        setMessageType("error");
      }
    } catch (err) {
      const msg = err.response?.data?.error || err.message || "Erreur serveur";
      setMessage(`❌ ${String(msg)}`);
      setMessageType("error");
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ marginBottom: '30px' }}>📷 Reconnaissance Faciale</h1>

      <div style={{ borderRadius: '16px', overflow: 'hidden', background: '#000', marginBottom: '30px' }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />
      </div>

      <button 
        onClick={handleCapture}
        disabled={loading}
        style={{
          padding: '16px 40px',
          fontSize: '18px',
          background: loading ? '#6b7280' : '#4F46E5',
          color: 'white',
          border: 'none',
          borderRadius: '10px',
          cursor: loading ? 'not-allowed' : 'pointer',
          marginBottom: '30px'
        }}
      >
        {loading ? '⏳ Analyse en cours...' : '🔍 Capturer & Analyser'}
      </button>

      {message && (
        <div style={{
          padding: '25px',
          borderRadius: '12px',
          fontSize: '20px',
          backgroundColor: messageType === 'success' ? '#DCFCE7' : '#FEE2E2',
          color: messageType === 'success' ? '#166534' : '#991B1B',
          border: `3px solid ${messageType === 'success' ? '#86EFAC' : '#FECACA'}`
        }}>
          {message}
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
